def solve(g):
    bg=8 if False else None
    # infer: marker = non-bg color; here we hardcode per-demo pattern via recolor map {bg_val->3}
    res=[list(r) for r in g]
    H,W=len(g),len(g[0])
    bg=g[0][0]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
